pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";const{jsPDF:jsPDF}=window.jspdf,dropZone=document.getElementById("drop-zone"),fileInput=document.getElementById("file-input"),textEditor=document.getElementById("text-editor"),preview=document.getElementById("handwritten-preview"),generateBtn=document.getElementById("generate-pdf");let activeFont="Dancing Script";function setStyle(e,t){activeFont=e,preview.style.fontFamily=`'${e}', cursive`,document.querySelectorAll(".style-btn").forEach(e=>e.classList.remove("active")),t.classList.add("active")}async function processFile(e){if(!e)return;const t=await e.arrayBuffer(),n=await pdfjsLib.getDocument(t).promise;let o="";for(let e=1;e<=n.numPages;e++){const t=await n.getPage(e);o+=(await t.getTextContent()).items.map(e=>e.str).join(" ")+"\n"}textEditor.value=o,preview.innerText=o,document.getElementById("file-status").innerText=`Loaded: ${e.name}`}dropZone.onclick=()=>fileInput.click(),fileInput.onchange=e=>processFile(e.target.files[0]),textEditor.oninput=()=>{preview.innerText=textEditor.value||"Start typing or upload a PDF to see the handwriting preview here..."},generateBtn.onclick=()=>{const e=new jsPDF,t=textEditor.value;e.setFont("courier","normal"),e.setFontSize(14);const n=e.splitTextToSize(t,170);let o=20;n.forEach(t=>{o>280&&(e.addPage(),o=20),e.text(t,20,o),o+=10}),e.save("handwritten_document.pdf"),setTimeout(()=>{const t=document.createElement("a");t.href=e.output("bloburl"),t.download="handwritten_document.pdf",t.click()},1e3)};